export interface WebhookDelivery {
  id: string;
  /** The id inside the delivered body and the Payrudder-Event-Id header */
  event_id: string;
  /** A WebhookEventType, or ping for the test event */
  event_type: string;
  endpoint_id: string;
  state: "WEBHOOK_DELIVERY_STATE_PENDING" | "WEBHOOK_DELIVERY_STATE_DELIVERED" | "WEBHOOK_DELIVERY_STATE_FAILED";
  attempts: number;
  /** Set while the delivery is pending */
  next_attempt_time: string | null;
  /** HTTP status of the last attempt; 0 when no attempt got an answer */
  last_status: number;
  last_error: string;
  create_time: string | null;
  /** Set once the endpoint answered 2xx */
  delivered_time: string | null;
}

export interface WebhookEndpoint {
  id: string;
  url: string;
  description: string;
  event_types: Array<string>;
  active: boolean;
  /** whsec_…; only in the response of create and rotate-secret */
  secret: string;
  create_time: string | null;
}

export interface WebhookEndpointInput {
  /** https only, a public address, no credentials */
  url: string;
  description?: string;
  /** Empty means every type */
  event_types?: Array<WebhookEventType>;
  /** A PUT replaces the endpoint: leaving active out deactivates it */
  active: boolean;
}

export type WebhookEventType = "invoice.finalized" | "invoice.paid" | "invoice.voided" | "invoice.uncollectible" | "credit_note.created" | "credit_note.refunded" | "credit_note.refund_failed" | "subscription.created" | "subscription.changed" | "subscription.change_scheduled" | "subscription.cancelled" | "subscription.cancellation_scheduled" | "subscription.cancellation_withdrawn" | "subscription.paused" | "subscription.resumed" | "subscription.moved_to_provider" | "subscription.trial_will_end" | "payment_link.created" | "payment_link.paid" | "payment_link.expired" | "payment.disputed" | "credits.purchased" | "credits.low" | "customer.blocked" | "customer.unblocked" | "price_change.scheduled" | "contract.accepted" | "contract.version_published" | "contract.withdrawal_requested" | "contract.withdrawal_decided";

export interface WithdrawPriceChangeResponse {
  price_change: PriceChange;
  /** How many waiting changes this call cancelled */
  withdrawn: number;
}
